        form = record.get('form')
        start = record.get('start_date')
        end = record.get('end_date')
        date = record.get('as_of_date')
        valid_time = (form == 'ongoing_since' and type(start) is str and end is None and date is None) or (form == 'closed_interval' and type(start) is str and type(end) is str and date is None) or (form == 'active_on_date' and start is None and end is None and type(date) is str) or (form == 'undated' and start is None and end is None and date is None)
        if evidence is None or type(person) is not str or type(term) is not str or form not in ('ongoing_since', 'closed_interval', 'active_on_date', 'undated') or not valid_time:
            complete = False
            continue
        quote = ' '.join(row['quote'].lower() for row in evidence)
        if person.lower() not in quote or term.lower() not in quote:
            complete = False
            add(reasons, 'nonresident_alien_role_not_source_explicit')
            continue
        for row in evidence:
            add(witnesses, row)
        event = 'nonresident_alien_' + str(index)
        put(facts, 'nonresident_alien_', [event])
        put(facts, 'agent_', [event, person])
        if form in ('ongoing_since', 'closed_interval'):
            put(facts, 'start_', [event, start])
        if form == 'closed_interval':
            put(facts, 'end_', [event, end])
        if form == 'active_on_date':
            put(facts, 'start_', [event, date])
            put(facts, 'end_', [event, date])
